#!/usr/bin/env python3
"""Stage robokit's HF RLDS batches as OXE-registered datasets for MemoryVLA training.

Source: any HF dataset repo laid out like `shaohuan1/Memoryvla` — top-level dirs named
`<task>_b<N>/robokit_dataset/<version>/{dataset_info.json,features.json,*.tfrecord-*}`,
one such dir per collection batch, batches grouped by task via a shared `<task>_b` prefix.

What this script does, per batch:
  1. Downloads only the RLDS folder (no HDF5) via `snapshot_download`.
  2. Symlinks it into `<out>/<task>_b<N>/<version>/` — a flat, TFDS-loadable directory.
  3. Registers `<task>_b<N>` as an OXE dataset name in the target MemoryVLA codebase
     (reusing the existing single-camera/no-wrist `robokit_dataset` config + transform),
     and (re)writes a `lememory_<task>` mixture plus a combined `lememory_all`.

Nothing here touches training hyperparameters — that's still `train.py`'s CLI / the
shell scripts under `script/train/`. This only makes `--data_root_dir <out>
--vla.data_mix lememory_<task>` resolve to real data.

Idempotent: re-running only downloads batches that are new, and always regenerates the
mixture block (bounded by lememoryvla:auto-generated markers) so newly-published
batches get picked up without hand-editing anything. Publishing is per-file and can be
in flight while this runs, so every batch is first probed on the Hub for a *complete*
RLDS version (`dataset_info.json` present and all of its shards uploaded); batches that
aren't there yet are reported and skipped, not downloaded and not registered. A task
with zero complete batches is likewise skipped with a warning, not an error — rerun
later once the upload has landed.

See README.md in this folder for the full walkthrough.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import re
from collections import defaultdict
from pathlib import Path

from huggingface_hub import HfApi, hf_hub_download, snapshot_download
from huggingface_hub.utils import EntryNotFoundError

DEFAULT_SOURCE_REPO = "shaohuan1/Memoryvla"
DEFAULT_OUT = "~/tensorflow_datasets/lememoryvla"
# This script lives at <codebase>/lememoryvla/prepare_data.py, so its own grandparent
# is the codebase root by construction.
DEFAULT_CODEBASE = Path(__file__).resolve().parent.parent

# Known task-prefix -> short, shell-friendly alias for the generated `lememory_<alias>`
# mixture name. Anything discovered that isn't listed here still works — it just gets
# an auto-derived alias instead of a hand-picked one.
FRIENDLY_ALIASES = {
    "Stack_one_cup_on_top_of_another_cup": "stack_one_cup",
    "Cover_the_building_block_with_a_cup,_then_lift_up_the_cup_covering_the_block.": "cover_block",
}

BATCH_RE = re.compile(r"^(?P<task>.+)_b(?P<num>\d+)$")

BEGIN_MARKER = "# >>> lememoryvla:auto-generated (regenerated by lememoryvla/prepare_data.py -- do not hand-edit) >>>"
END_MARKER = "# <<< lememoryvla:auto-generated <<<"

# Same base contract as the (now-retired) scripts/memvla_register_dataset.py: single
# third-person camera, no wrist, continuous (non-binarized) gripper. Appended once and
# left alone afterwards -- every per-batch dataset just reuses this.
BASE_CONFIG_BLOCK = '''

# === robokit (Piper single-arm, single third-person camera) ===
# Differs from the codebase's own piper_dataset: wrist is None (no wrist camera in
# robokit's current collection setup).
OXE_DATASET_CONFIGS["robokit_dataset"] = {
    "image_obs_keys": {"primary": "image", "secondary": None, "wrist": None},
    "depth_obs_keys": {"primary": None, "secondary": None, "wrist": None},
    "state_obs_keys": ["EEF_state", None, "gripper_state"],
    "state_encoding": StateEncoding.POS_EULER,
    "action_encoding": ActionEncoding.EEF_POS,
}
'''

BASE_TRANSFORM_BLOCK = '''

def robokit_dataset_transform(trajectory: Dict[str, Any]) -> Dict[str, Any]:
    """robokit RLDS: action = [local delta pose (6), gripper], meters / radians / xyz extrinsic euler.

    Same shape as the codebase's own piper_dataset_transform (split state into the
    proprio keys the config expects), but deliberately does NOT binarize the gripper --
    the 7th dim is a continuous opening, and binarizing would turn a smooth grasp into
    a full-stroke step.
    """
    if "state" in trajectory["observation"]:
        trajectory["observation"]["EEF_state"] = trajectory["observation"]["state"][:, :6]
        trajectory["observation"]["gripper_state"] = trajectory["observation"]["state"][:, -1:]
    return trajectory


OXE_STANDARDIZATION_TRANSFORMS["robokit_dataset"] = robokit_dataset_transform
'''

# The codebase resolves an OXE dataset name with `tfds.builder(name, data_dir=...)`, which
# only finds datasets that have a registered Python builder class -- and refuses outright
# any name containing "," or ".". Our batch dirs are named after the task prompt, so on a
# stock checkout every one of them fails to load (measured on tfds 4.9.10:
# DatasetNotFoundError for `Stack_one_cup_..._b0`, ValueError for the cover-block name).
# `builder_from_directory` just reads the staged directory and has neither restriction.
LOADER_CALL_SITE = "    builder = tfds.builder(name, data_dir=data_dir)\n"

LOADER_PATCH_BLOCK = '''    def _lememoryvla_local_builder(name: str, data_dir: str):
        """Load a generated TFDS directory when no Python builder class is registered."""
        from pathlib import Path

        data_root = Path(data_dir).expanduser()

        def is_builder_dir(path: Path) -> bool:
            return (path / "dataset_info.json").is_file() and (path / "features.json").is_file()

        for candidate in (data_root, data_root / name):
            if is_builder_dir(candidate):
                return tfds.builder_from_directory(str(candidate))
        dataset_root = data_root / name
        if dataset_root.is_dir():
            versions = sorted(c for c in dataset_root.iterdir() if c.is_dir() and is_builder_dir(c))
            if versions:
                return tfds.builder_from_directory(str(versions[-1]))
        return None

    try:
        builder = tfds.builder(name, data_dir=data_dir)
    except Exception:
        builder = _lememoryvla_local_builder(name, data_dir)
        if builder is None:
            raise
'''

BASE_MIXTURE_BLOCK = '''

# Single-dataset mixture: pass data_mix="robokit" to train on one robokit_dataset dir.
OXE_NAMED_MIXTURES["robokit"] = [
    ("robokit_dataset", 1.0),
]
'''


def append_once(path: Path, marker: str, block: str) -> bool:
    text = path.read_text()
    if marker in text:
        return False
    path.write_text(text + block)
    return True


def replace_generated_block(path: Path, body: str) -> None:
    text = path.read_text()
    block = f"\n{BEGIN_MARKER}\n{body}{END_MARKER}\n"
    if BEGIN_MARKER in text:
        pre, rest = text.split(BEGIN_MARKER, 1)
        _, post = rest.split(END_MARKER, 1)
        text = pre + block + post
    else:
        text = text + block
    path.write_text(text)


def patch_loader(codebase: Path) -> None:
    """Teach the RLDS loader to fall back to `builder_from_directory` (see LOADER_CALL_SITE)."""
    path = codebase / "vla" / "datasets" / "rlds" / "dataset.py"
    if not path.is_file():
        raise SystemExit(f"can't find {path} -- wrong --codebase?")
    text = path.read_text()
    if "builder_from_directory" in text:
        print("[skip] dataset.py: builder_from_directory fallback already present")
        return
    if LOADER_CALL_SITE not in text:
        print(
            f"[WARN] dataset.py: expected line `{LOADER_CALL_SITE.strip()}` not found -- this checkout\n"
            "       differs from the upstream this patch was written against. Add the fallback by hand\n"
            "       (see 'RLDS 加载器补丁' in lememoryvla/README.md), or `tfds.builder` will reject the\n"
            "       batch dataset names and training will fail at data-loading time."
        )
        return
    path.write_text(text.replace(LOADER_CALL_SITE, LOADER_PATCH_BLOCK, 1))
    print("[ok]   dataset.py: added builder_from_directory fallback")


def register_base(codebase: Path) -> None:
    patch_loader(codebase)
    oxe = codebase / "vla" / "datasets" / "rlds" / "oxe"
    if not oxe.is_dir():
        raise SystemExit(f"can't find {oxe} -- wrong --codebase?")
    if append_once(oxe / "configs.py", 'OXE_DATASET_CONFIGS["robokit_dataset"]', BASE_CONFIG_BLOCK):
        print("[ok]   configs.py: registered base robokit_dataset config")
    else:
        print("[skip] configs.py: base robokit_dataset config already present")
    if append_once(oxe / "transforms.py", "def robokit_dataset_transform", BASE_TRANSFORM_BLOCK):
        print("[ok]   transforms.py: registered robokit_dataset_transform")
    else:
        print("[skip] transforms.py: robokit_dataset_transform already present")
    if append_once(oxe / "mixtures.py", 'OXE_NAMED_MIXTURES["robokit"]', BASE_MIXTURE_BLOCK):
        print("[ok]   mixtures.py: registered base \"robokit\" mixture")
    else:
        print("[skip] mixtures.py: base \"robokit\" mixture already present")


def register_batches(codebase: Path, batches_by_task: dict[str, list[str]]) -> None:
    oxe = codebase / "vla" / "datasets" / "rlds" / "oxe"
    all_names = sorted(name for names in batches_by_task.values() for name in names)

    configs_body = "".join(
        f'OXE_DATASET_CONFIGS["{name}"] = dict(OXE_DATASET_CONFIGS["robokit_dataset"])\n' for name in all_names
    )
    replace_generated_block(oxe / "configs.py", configs_body)

    transforms_body = "".join(
        f'OXE_STANDARDIZATION_TRANSFORMS["{name}"] = robokit_dataset_transform\n' for name in all_names
    )
    replace_generated_block(oxe / "transforms.py", transforms_body)

    lines = []
    for task_prefix, names in sorted(batches_by_task.items()):
        alias = task_alias(task_prefix)
        lines.append(f'OXE_NAMED_MIXTURES["lememory_{alias}"] = [\n')
        for name in names:
            lines.append(f'    ("{name}", 1.0),\n')
        lines.append("]\n")
    if all_names:
        lines.append('OXE_NAMED_MIXTURES["lememory_all"] = [\n')
        for name in all_names:
            lines.append(f'    ("{name}", 1.0),\n')
        lines.append("]\n")
    replace_generated_block(oxe / "mixtures.py", "".join(lines))

    print(f"[ok]   registered {len(all_names)} batch dataset(s) across {len(batches_by_task)} task(s)")


def task_alias(task_prefix: str) -> str:
    if task_prefix in FRIENDLY_ALIASES:
        return FRIENDLY_ALIASES[task_prefix]
    normalized = re.sub(r"[^a-z0-9]+", "_", task_prefix.lower()).strip("_")
    if len(normalized) <= 40:
        return normalized
    digest = hashlib.sha1(task_prefix.encode()).hexdigest()[:8]
    short = "_".join(normalized.split("_")[:4])[:32].strip("_")
    return f"{short}_{digest}"


def probe_batch(source_repo: str, batch_dir: str) -> dict | None:
    """Newest *complete* RLDS version published under a batch dir, or None if there's none yet.

    Complete means: `dataset_info.json` and `features.json` are both there, and the repo
    actually holds every shard `dataset_info.json` says exists. Uploads land file by file,
    so a batch dir showing up on the Hub is no proof its RLDS is finished -- half of it
    would train fine and silently drop episodes. Prints why a batch didn't qualify.
    """
    api = HfApi()
    try:
        entries = api.list_repo_tree(
            source_repo, repo_type="dataset", path_in_repo=f"{batch_dir}/robokit_dataset", recursive=True
        )
        files_by_version: dict[str, set[str]] = defaultdict(set)
        for entry in entries:
            parts = entry.path.split("/")
            if len(parts) == 4:  # <batch>/robokit_dataset/<version>/<file>
                files_by_version[parts[2]].add(parts[3])
    except EntryNotFoundError:
        return None

    for version in sorted(files_by_version, reverse=True):
        names = files_by_version[version]
        if not {"dataset_info.json", "features.json"} <= names:
            continue
        info_path = hf_hub_download(
            source_repo, f"{batch_dir}/robokit_dataset/{version}/dataset_info.json", repo_type="dataset"
        )
        split = json.loads(Path(info_path).read_text())["splits"][0]
        shards = [int(n) for n in split["shardLengths"]]
        uploaded = len([n for n in names if ".tfrecord" in n])
        if uploaded < len(shards):
            print(f"[warn] {batch_dir}: v{version} still uploading ({uploaded}/{len(shards)} shards) -- skipped")
            continue
        return {"version": version, "episodes": sum(shards), "shards": len(shards)}
    print(f"[warn] {batch_dir}: no complete RLDS published yet -- skipped")
    return None


def discover_batches(source_repo: str, only: list[str] | None) -> dict[str, list[tuple[str, dict]]]:
    """Group top-level repo entries into {task_prefix: [(batch_dir, probe), ...]} by batch number."""
    entries = HfApi().list_repo_tree(source_repo, repo_type="dataset", recursive=False)
    by_task: dict[str, list[tuple[int, str, dict]]] = defaultdict(list)
    for entry in entries:
        match = BATCH_RE.match(entry.path)
        if not match:
            # Anything not named `<task>_b<N>` isn't a published batch -- e.g. Memoryvla's
            # legacy `stack_cups/`. Say so rather than silently leaving data on the table.
            if hasattr(entry, "tree_id"):
                print(f"[warn] {entry.path!r}: not a `<task>_b<N>` batch dir -- ignored")
            continue
        task_prefix = match.group("task")
        if only and not any(o.lower() in task_prefix.lower() for o in only):
            continue
        probe = probe_batch(source_repo, entry.path)
        if probe is None:
            continue
        by_task[task_prefix].append((int(match.group("num")), entry.path, probe))
    return {task: [(name, probe) for _, name, probe in sorted(rows)] for task, rows in sorted(by_task.items())}


def stage_batch(batch_dir: str, version: str, snapshot_root: Path, out_root: Path) -> dict:
    src_version_dir = snapshot_root / batch_dir / "robokit_dataset" / version
    if not ((src_version_dir / "dataset_info.json").is_file() and (src_version_dir / "features.json").is_file()):
        raise RuntimeError(f"{batch_dir}: no dataset_info.json/features.json under {src_version_dir}")

    dst_version_dir = out_root / batch_dir / src_version_dir.name
    dst_version_dir.mkdir(parents=True, exist_ok=True)
    for source_file in src_version_dir.iterdir():
        link = dst_version_dir / source_file.name
        if link.exists() or link.is_symlink():
            continue
        link.symlink_to(source_file.resolve())

    info = json.loads((dst_version_dir / "dataset_info.json").read_text())
    episodes = sum(int(n) for n in info["splits"][0]["shardLengths"])
    return {
        "version": src_version_dir.name,
        "episodes": episodes,
        "shards": len(info["splits"][0]["shardLengths"]),
    }


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--source-repo", default=DEFAULT_SOURCE_REPO)
    parser.add_argument("--out", default=DEFAULT_OUT, help="shared data_root_dir for all staged datasets")
    parser.add_argument("--codebase", default=str(DEFAULT_CODEBASE), help="path to the MemoryVLA-openvla-codebase checkout")
    parser.add_argument(
        "--only",
        action="append",
        help="substring filter on task prefix, e.g. --only Stack_one_cup (repeatable; default: all tasks found)",
    )
    parser.add_argument("--list", action="store_true", help="only discover and print, don't download or register")
    parser.add_argument("--skip-register", action="store_true", help="stage data but don't touch --codebase")
    args = parser.parse_args()

    by_task = discover_batches(args.source_repo, args.only)
    if not by_task:
        raise SystemExit(
            f"no fully-published `<task>_b<N>` directories found in {args.source_repo} (filters: {args.only})"
        )

    print(f"\nFound in {args.source_repo}:")
    for task_prefix, batches in by_task.items():
        print(f"  {task_prefix!r} -> {len(batches)} batch(es):")
        for batch_dir, probe in batches:
            print(f"      {batch_dir}: {probe['episodes']} episodes, {probe['shards']} shards, v{probe['version']}")
    if args.list:
        return

    out_root = Path(args.out).expanduser().resolve()
    out_root.mkdir(parents=True, exist_ok=True)

    all_batches = [row for batches in by_task.values() for row in batches]
    snapshot_root = Path(
        snapshot_download(
            repo_id=args.source_repo,
            repo_type="dataset",
            allow_patterns=[f"{b}/robokit_dataset/{probe['version']}/*" for b, probe in all_batches],
        )
    )

    staged_by_task: dict[str, list[str]] = defaultdict(list)
    print("\nStaging:")
    for task_prefix, batches in by_task.items():
        for batch_dir, probe in batches:
            result = stage_batch(batch_dir, probe["version"], snapshot_root, out_root)
            staged_by_task[task_prefix].append(batch_dir)
            print(
                f"  {batch_dir}: {result['episodes']} episodes, {result['shards']} shards, "
                f"v{result['version']} -> {out_root / batch_dir / result['version']}"
            )

    if args.skip_register:
        print("\n--skip-register: not touching the codebase's OXE registry.")
    else:
        codebase = Path(args.codebase).expanduser().resolve()
        print(f"\nRegistering against {codebase}:")
        register_base(codebase)
        register_batches(codebase, dict(staged_by_task))

    print(f"\ndata_root_dir = {out_root}")
    print("data_mix options:")
    for task_prefix in staged_by_task:
        print(f'  lememory_{task_alias(task_prefix)}   ({task_prefix!r})')
    if len(staged_by_task) > 1:
        print("  lememory_all   (all of the above combined)")


if __name__ == "__main__":
    main()
